import logging
import httpx
from typing import List, Dict, Optional
from sqlalchemy import text
from sqlalchemy.orm import Session

from .config import settings
from .db import SessionLocal

logger = logging.getLogger("kruschlaw.rag")

UPL_DISCLAIMER = (
    "DISCLAIMER: This analysis was generated by KruschLaw, an offline, air-gapped AI research engine. "
    "This material is provided strictly for exploratory legal research and preliminary issue-spotting. "
    "It does NOT constitute legal advice, formal representation, or an attorney-client relationship. "
    "A licensed attorney admitted to practice in the relevant jurisdiction must independently verify "
    "all cited statutes, local ordinances, and analytical conclusions prior to taking any formal legal action."
)


def get_embedding(query: str) -> List[float]:
    """Generate a vector embedding via Ollama API."""
    if not query or not query.strip():
        raise ValueError("Cannot embed empty text.")

    payload = {
        "model": settings.OLLAMA_EMBED_MODEL,
        "input": query
    }

    try:
        with httpx.Client(timeout=settings.EMBED_TIMEOUT) as client:
            resp = client.post(f"{settings.OLLAMA_EMBED_HOST}/api/embed", json=payload)
            
            # If /api/embed fails with 404, fallback to legacy /api/embeddings endpoint
            if resp.status_code == 404:
                resp = client.post(
                    f"{settings.OLLAMA_EMBED_HOST}/api/embeddings",
                    json={"model": settings.OLLAMA_EMBED_MODEL, "prompt": query}
                )
                resp.raise_for_status()
                embedding = resp.json().get("embedding", [])
                if embedding:
                    return embedding
                raise ValueError("Legacy Ollama endpoint returned empty embedding.")
                
            resp.raise_for_status()
            data = resp.json()
            embeddings = data.get("embeddings", [])
            if embeddings and len(embeddings) > 0 and len(embeddings[0]) > 0:
                return embeddings[0]
            raise ValueError(f"Ollama returned unexpected payload structure: {data}")
            
    except httpx.ConnectError as e:
        logger.error(f"Failed to connect to Ollama embedding service at {settings.OLLAMA_EMBED_HOST}: {e}")
        raise ConnectionError(
            f"Could not connect to Ollama at {settings.OLLAMA_EMBED_HOST}. "
            f"Please verify Ollama is running and has the '{settings.OLLAMA_EMBED_MODEL}' model pulled."
        ) from e
    except Exception as e:
        logger.error(f"Embedding generation error: {e}")
        raise


def retrieve_laws(
    query_vector: List[float],
    limit: Optional[int] = None,
    state_filter: Optional[str] = None,
    city_filter: Optional[str] = None,
    db_session: Optional[Session] = None
) -> List[Dict]:
    """Retrieve laws matching the query embedding using cosine similarity."""
    limit = limit or settings.DEFAULT_RETRIEVAL_LIMIT
    close_session = False
    db = db_session
    if db is None:
        db = SessionLocal()
        close_session = True

    try:
        vec_str = '[' + ','.join(str(v) for v in query_vector) + ']'
        
        query_conditions = ["embedding IS NOT NULL"]
        params = {"vec": vec_str, "limit": limit}
        
        if state_filter:
            query_conditions.append("state = :state")
            params["state"] = state_filter.strip().upper()
        if city_filter:
            query_conditions.append("LOWER(city_or_county) = LOWER(:city)")
            params["city"] = city_filter.strip()
            
        conditions_str = " AND ".join(query_conditions)
        is_sqlite = db.bind.dialect.name == "sqlite"
        
        if is_sqlite:
            # Fallback for local unit test fixtures without pgvector extension
            sql = text(f"""
                SELECT id, jurisdiction, state, city_or_county, title, section, content,
                       1.0 AS cosine_sim
                FROM laws_vectors
                WHERE {conditions_str}
                LIMIT :limit
            """)
        else:
            # Production pgvector cosine distance: 1 - (embedding <=> vec)
            sql = text(f"""
                SELECT id, jurisdiction, state, city_or_county, title, section, content,
                       (1 - (embedding <=> CAST(:vec AS vector))) AS cosine_sim
                FROM laws_vectors
                WHERE {conditions_str}
                ORDER BY embedding <=> CAST(:vec AS vector)
                LIMIT :limit
            """)

        rows = db.execute(sql, params).fetchall()
        results = []
        for row in rows:
            results.append({
                "id": row.id,
                "jurisdiction": row.jurisdiction,
                "state": row.state,
                "city_or_county": row.city_or_county,
                "title": row.title,
                "section": row.section,
                "content": row.content,
                "similarity": float(row.cosine_sim) if row.cosine_sim is not None else 0.0
            })
        return results
    except Exception as e:
        logger.error(f"Vector search retrieval error: {e}")
        return []
    finally:
        if close_session:
            db.close()


def generate_legal_analysis(case_facts: str, case_title: str, laws: List[Dict]) -> str:
    """Generate structured legal analysis grounding client matter facts with retrieved laws."""
    if not laws:
        return (
            "### ⚠️ No Relevant Authorities Found\n\n"
            "No relevant statutes or ordinances were found in the database matching the matter facts. "
            "Please ensure you have ingested applicable municipal or state datasets.\n\n"
            f"> **Note**: {UPL_DISCLAIMER}"
        )

    # Format retrieved legal citations
    context_blocks = []
    for idx, law in enumerate(laws, 1):
        loc = []
        if law.get("state"):
            loc.append(f"State: {law['state']}")
        if law.get("city_or_county"):
            loc.append(f"Jurisdiction: {law['city_or_county']}")
        loc_str = ", ".join(loc) if loc else "Federal / General"
        
        sim_pct = round(law.get("similarity", 0.0) * 100, 1)
        block = (
            f"[{idx}] {law.get('title', 'Unknown Title')} — {law.get('section', 'General')}\n"
            f"Authority: {law.get('jurisdiction', 'Municipal Code')} ({loc_str}) [Relevance Match: {sim_pct}%]\n"
            f"Text:\n{law.get('content', '').strip()}\n"
        )
        context_blocks.append(block)

    context_str = "\n---\n".join(context_blocks)

    system_prompt = (
        "You are KruschLaw, an air-gapped, privacy-first legal research engine designed for law firms. "
        "Your task is to produce a rigorous, citation-grounded preliminary case analysis based ONLY on the provided "
        "statutes, municipal ordinances, and factual statement. Do not hallucinate authorities.\n\n"
        "Analyze the case using the following mandatory headings:\n"
        "1. **Executive Summary**: Core legal conclusion in 2-3 sentences.\n"
        "2. **Applicable Legal Authority & Statutory Citations**: Cite each relevant section by name and number.\n"
        "3. **Factual Matrix Analysis**: Connect specific facts from the matter to the statutory elements.\n"
        "4. **Potential Defenses, Liabilities & Next Steps**: Concrete strategic considerations for counsel."
    )

    user_prompt = f"""=== MATTER TITLE ===
{case_title}

=== MATTER FACTUAL RECORD ===
{case_facts}

=== RETRIEVED RELEVANT STATUTES & ORDINANCES ===
{context_str}

=== INSTRUCTIONS ===
Draft the legal analysis following the required headings. Conclude with an ethical reminder for counsel."""

    try:
        with httpx.Client(timeout=settings.LLM_TIMEOUT) as client:
            resp = client.post(
                f"{settings.OLLAMA_BASE_URL}/api/generate",
                json={
                    "model": settings.OLLAMA_LLM_MODEL,
                    "system": system_prompt,
                    "prompt": user_prompt,
                    "stream": False,
                    "options": {
                        "temperature": 0.2,
                        "num_ctx": 8192
                    }
                }
            )
            resp.raise_for_status()
            analysis_text = resp.json().get("response", "").strip()
            
            # Append formal UPL disclaimer
            full_response = f"{analysis_text}\n\n---\n\n> ⚖️ **Ethical & Regulatory Notice**:\n> {UPL_DISCLAIMER}"
            return full_response
            
    except httpx.ConnectError as e:
        return (
            f"### ❌ Inference Connection Error\n\n"
            f"Could not connect to the local LLM at `{settings.OLLAMA_BASE_URL}`. "
            f"Please verify that Ollama is active and that the model `{settings.OLLAMA_LLM_MODEL}` is loaded.\n\n"
            f"**Error Details**: {e}"
        )
    except Exception as e:
        return f"### ❌ Error Generating Analysis\n\nAn unexpected error occurred during analysis generation: {str(e)}"
